class Checker:
    def isIsomorphic(self, s, t, result):
        if not isinstance(result, bool):
            return False
        if len(s) != len(t):
            return result is False
        st = {}
        ts = {}
        for a, b in zip(s, t):
            if a in st and st[a] != b:
                return result is False
            if b in ts and ts[b] != a:
                return result is False
            st[a] = b
            ts[b] = a
        return result is True

